node <<'NODE'
const fs=require("node:fs"),cp=require("node:child_process"),crypto=require("node:crypto"),assert=require("node:assert/strict");
const d="docs/coordinator/worktree-completion/evidence/",commandPath=d+"dcc1-parity-observer-diagnostic-command.json",record=JSON.parse(fs.readFileSync(commandPath)),run=record.run,cwd=process.cwd();
