for(const x of pre.untracked){const n=info(x.path);for(const k of ["bytes","sha256","mode"])assert.equal(n[k],x[k],x.path+" "+k)}
for(const x of admission.preservation.record.copies){const n=info(x.preservedPath);assert.equal(n.bytes,x.bytes);assert.equal(n.sha256,x.sha256);assert.equal(n.mode,x.mode);const old=info(x.path);assert.equal(old.sha256,x.sha256);assert.equal(old.bytes,x.bytes);assert.equal(old.mode,x.mode);}
