const untracked=git("ls-files","--others","--exclude-standard","-z").split("\0").filter(Boolean);
assert.deepEqual(untracked.sort(),[...pre.untracked.map(x=>x.path),...extra].sort(),"exact declared non-execution inputs");
const index=git("write-tree").trim(),head=git("rev-parse","HEAD").trim(),merge=git("rev-parse","MERGE_HEAD").trim();assert.equal(index,pre.index);assert.equal(head,pre.head);assert.equal(merge,pre.merge);
const files=git("ls-files","-s").trimEnd().split("\n").filter(l=>!l.includes("\tdocs/coordinator/worktree-completion/")).map(line=>{const[m,path]=line.split("\t"),[mode,expected,stage]=m.split(" ");const b=mode==="120000"?Buffer.from(fs.readlinkSync(path)):fs.readFileSync(path),blob=sha(Buffer.concat([Buffer.from("blob "+b.length+"\0"),b]),"sha1");assert.equal(stage,"0");assert.equal(blob,run.inputs[path]===undefined?expected:run.inputs[path],path);return{path,mode,bytes:b.length,sha256:sha(b),blob,indexBlob:expected};});
const by=new Map(files.map(x=>[x.path,x.blob]));const closureStream=git("ls-tree","-r","--full-tree",index).split("\n").filter(l=>l&&!/\tdocs\/coordinator\/worktree-completion\/(reports|evidence|handoffs)\//.test(l)).map(l=>{const[m,p]=l.split("\t");assert(by.has(p));return m.replace(/[0-9a-f]{40}$/,by.get(p))+"\t"+p}).join("\n")+"\n";
assert.equal(sha(closureStream),"7539930ac1b653fda3c84071d0406efa2313d509d3f71b79fe16e8b55c933bbb");
const proposed=JSON.parse(fs.readFileSync(d+"dcc1-parity-observer-proof-preflight.json")).proposed.map(x=>x.path);
const rawPath=d+"dcc1-parity-observer-diagnostic.raw.log",metaPath=d+"dcc1-parity-observer-diagnostic.meta.jsonl";
for(const p of [...proposed,rawPath,metaPath])assert(!fs.existsSync(p),"exclusive output exists "+p);
const raw=fs.openSync(rawPath,"wx",0o600),meta=fs.openSync(metaPath,"wx",0o600),errors=[],start=new Date().toISOString(),mono=process.hrtime.bigint();let bytes=0;const digest=crypto.createHash("sha256");
const put=(fd,b)=>{let n=0;while(n<b.length)n+=fs.writeSync(fd,b,n,b.length-n);fs.fsyncSync(fd)};
const log=x=>put(meta,Buffer.from(JSON.stringify(x)+"\n"));
log({event:"start",start,command:run.command,executable:run.executable,args:run.args,environment:run.environment,cwd,head,merge,index,inputs:files,executionClosure:sha(closureStream),closureStream,dependencies:pre.dependencies,npmGraphSha256:pre.npmGraphSha256,commandFile:info(commandPath),nonExecutionInputs:extra.map(info),referenceTree:git("rev-parse",index+":tests/parity/references").trim(),classification:"Actual contemporaneous complete working-file input map persisted and fsynced BEFORE child spawn; raw child bytes in stdout/stderr callback arrival order."});
const runner=proposed.at(-1);fs.mkdirSync(runner,{mode:0o700});log({event:"runner-reserved",at:new Date().toISOString(),path:runner,meaning:"Exclusive new empty runner directory, not a capture. Playwright owns its normal output lifecycle."});
const child=cp.spawn(run.executable,run.args,{cwd,env:process.env,stdio:["ignore","pipe","pipe"]});log({event:"spawn",at:new Date().toISOString(),pid:child.pid});
function capture(b,channel){try{put(raw,b);bytes+=b.length;digest.update(b)}catch(e){errors.push({phase:"raw-write",message:String(e)})}process[channel].write(b)}
child.stdout.on("data",b=>capture(b,"stdout"));child.stderr.on("data",b=>capture(b,"stderr"));child.on("error",e=>errors.push({phase:"spawn",message:String(e)}));
child.on("close",(gateExit,signal)=>{const end=new Date().toISOString();try{fs.fsyncSync(raw);fs.closeSync(raw)}catch(e){errors.push({phase:"raw-close",message:String(e)})}
const terminal={event:"terminal",start,end,elapsedSeconds:Number(process.hrtime.bigint()-mono)/1e9,gateExit,signal,loggerExit:errors.length?1:0,errors,rawBytes:bytes,rawSha256:digest.digest("hex"),executionClosure:sha(closureStream),index,pid:child.pid};
try{log(terminal);fs.closeSync(meta)}catch(e){terminal.loggerExit=1;terminal.errors.push({phase:"meta-terminal",message:String(e)})}
process.stdout.write("\nLOGGER_TERMINAL "+JSON.stringify(terminal)+"\n");process.exitCode=gateExit===0?terminal.loggerExit:(gateExit===null?1:gateExit);});
