const d="docs/coordinator/worktree-completion/evidence/",sha=(b,a="sha256")=>crypto.createHash(a).update(b).digest("hex"),git=(...a)=>cp.execFileSync("git",a,{encoding:"utf8"}),failures=[];
const check=(ok,label)=>{if(!ok)failures.push(label)},info=p=>{const s=fs.lstatSync(p),b=fs.readFileSync(p);return{path:p,bytes:b.length,sha256:sha(b),mode:s.mode&4095,regular:s.isFile()&&!s.isSymbolicLink()}};
