const pins=["tests/parity/helpers/capture.ts","tests/unit/architecture/parity-reference-authority.test.ts","tests/parity/helpers/reference-store.ts"].map(p=>entries.find(x=>x.path===p));
const absent=[...proof.proposed.map(x=>x.path),d+"dcc1-parity-observer-diagnostic.raw.log",d+"dcc1-parity-observer-diagnostic.meta.jsonl"].map(p=>({path:p,absent:!fs.existsSync(p)}));for(const x of absent)check(x.absent,"absent "+x.path);
