const expected=[...pre.untracked.map(x=>x.path),...declared];const missing=expected.filter(p=>!actual.includes(p)),unexpected=actual.filter(p=>!expected.includes(p));
const ignore=cp.spawnSync("git",["check-ignore","-v","--stdin"],{input:missing.join("\n")+"\n",encoding:"utf8"});check(unexpected.length===0,"unexpected visible files");check(missing.length===107,"107 preserved ignored files");check(ignore.status===0,"ignore evidence");
const actualPreserved=[];function walk(p){for(const e of fs.readdirSync(p,{withFileTypes:true})){const q=path.join(p,e.name);if(e.isDirectory())walk(q);else actualPreserved.push(q)}}walk(admission.preservation.record.root);check(JSON.stringify(actualPreserved.sort())===JSON.stringify(copies.map(x=>x.path).sort()),"exact physical preservation membership");
