const stamp=info(old.bundle.stampFile.path);
console.log(JSON.stringify({classification:"Read-only post-release/restoration and launcher-set diagnosis; not a retry or browser run",at:new Date().toISOString(),head,merge,index,executionClosure:sha(stream),trackedCount:entries.length,referenceCount:refs.length,pins,originals,copies,retainedCount:retained.length,dependencies:pre.dependencies,absent,originalStamp:stamp,oldStamp:old.bundle.stamp,declaredNewFiles:declared.map(info),visibleUntrackedCount:actual.length,expectedVisibleComparisonCount:expected.length,ignoredPreserved:missing,unexpected,ignoreCommand:{executable:"git",args:["check-ignore","-v","--stdin"],exit:ignore.status,stdout:ignore.stdout,stderr:ignore.stderr},checks,unstaged:git("diff","--name-only"),unmerged:git("ls-files","-u"),failures,pass:failures.length===0}));
